// Protection) does not affect the behavior of EnterpriseDataProtection. The EDPEnforcementLevel
// from Policy CSP should be used to enable and disable Windows Information Protection (formerly
// known as Enterprise Data Protection).
func (s *AppLocker) GetLaunchControlGroupingStoreAppsEnforcementMode(ctx context.Context, grouping string) (string, error) {
	v, err := s.c.Get(ctx, URILaunchControlGroupingStoreAppsEnforcementMode(grouping))
	if err != nil {
		return "", err
	}
	return v.Str(), nil
}

