func (s *AppLocker) UpdateLaunchControlGroupingStoreAppsEnforcementMode(ctx context.Context, grouping string, value string) error {
	return s.c.Replace(ctx, URILaunchControlGroupingStoreAppsEnforcementMode(grouping), client.Chr(value))
}

